unsafe fn vnni_recursive_word_dot(a:*const i16,b:*const i16,terms:usize,out:*mut i32){unsafe{let mut acc=_mm512_setzero_si512();for pair in 0..terms.div_ceil(2){acc=_mm512_dpwssd_epi32(acc,_mm512_loadu_si512(a.add(pair*32).cast()),_mm512_loadu_si512(b.add(pair*32).cast()));}_mm512_storeu_si512(out.cast(),acc);}}
fn check_dot(a:&[[i16;16]],b:&[[i16;16]])->(u64,Vec<i32>,Vec<i64>){let n=a.len();assert_eq!(b.len(),n);let mut aa=vec![0i16;n.div_ceil(2)*32];let mut bb=aa.clone();let mut wide=vec![0i64;16];for k in 0..n{for lane in 0..16{aa[(k/2)*32+lane*2+k%2]=a[k][lane];bb[(k/2)*32+lane*2+k%2]=b[k][lane];wide[lane]+=a[k][lane]as i64*b[k][lane]as i64;}}let mut out=vec![0i32;16];unsafe{vnni_recursive_word_dot(aa.as_ptr(),bb.as_ptr(),n,out.as_mut_ptr());}for(l,v)in out.iter().enumerate(){assert_eq!(*v,wide[l]as i32);}let overflow=wide.iter().filter(|v|**v<i32::MIN as i64||**v>i32::MAX as i64).count()as u64;(overflow,out,wide)}
